class ProviderConfig:
    required = ("region",)

    def __init__(self, name, **options):
        self.name = name
        self.options = options
        missing = [r for r in self.required if r not in options]
        if missing:
            raise ValueError(f"missing required options: {missing}")

    def resource_defaults(self):
        return {"provider": self.name, "region": self.options["region"]}


aws_main = ProviderConfig("aws", region="us-east-1")
aws_backup = ProviderConfig("aws", region="eu-west-1", alias="backup")

for cfg in (aws_main, aws_backup):
    print(cfg.resource_defaults())
